SELECT *
FROM shopwizard.tOrdOrderWork

    AND OrderNo = #{pOrderNo}
    AND OrderName = #{pOrderName}
    AND RecverName = #{pRecverName}
    AND ChnlOrderNo = #{pChnlOrderNo}
    AND ShopCode = #{pShopCode}
    AND ShopProdCode = #{pShopProdCode}
    AND ProdName = #{pProdName}
    AND ChnlName = #{pChnlName}

        AND ChnlName IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')


        AND ChnlName NOT IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')


        AND NOT EXISTS ( SELECT OrderNo FROM shopwizard.tOrdCurrOrderProd WHERE shopwizard.tOrdCurrOrderProd.OrderNo = shopwizard.tOrdOrderWork.OrderNo )



    ORDER BY ${sidx} ${sord}
    ORDER BY CodeCheckYn, ShopProdCode, ProdName, ItemName
    ORDER BY BuyPrice, ProdName, ItemName

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderWork

    AND OrderNo = #{pOrderNo}
    AND OrderName = #{pOrderName}
    AND RecverName = #{pRecverName}
    AND ChnlOrderNo = #{pChnlOrderNo}
    AND ShopCode = #{pShopCode}
    AND ShopProdCode = #{pShopProdCode}
    AND ProdName = #{pProdName}
    AND ChnlName = #{pChnlName}

        AND ChnlName IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')


        AND ChnlName NOT IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')


        AND NOT EXISTS ( SELECT OrderNo FROM shopwizard.tOrdCurrOrderProd WHERE shopwizard.tOrdCurrOrderProd.OrderNo = shopwizard.tOrdOrderWork.OrderNo )

