    #{prodQty}, #{vatRate}, #{salePrice}, #{supplyPrice}, #{buyPrice}, #{deliFeeType}, #{deliFeeAmt}, #{promotFeeAmt},
    #{chnlName}, #{deliMemo}, #{giftDesc}, #{shipPlace}, #{bundleYn}, #{eventName}
)
